for c in cs:
 x=c['stsEffectProposal'];families=list(dict.fromkeys(by[m['buildId']]['characterId'] for m in c['memberships']));links='／'.join(by[m['buildId']]['characterName']+'・'+by[m['buildId']]['name'] for m in c['memberships']) or '未所属：'+c['remainderId']
 parts.append('<article class="effect-card" id="c-'+c['termId']+'" data-character="'+e(' '.join(families) if families else 'remaining')+'" data-type="'+e(x['type'])+'"><h2>'+e(c['name'])+'</h2><code>'+e(c['id'])+'</code><p>'+e(links)+'</p><span class="badge">'+e(x['type'])+'</span><span class="badge">エナジー '+str(x['energy'])+'</span><span class="badge">'+e(x['rarity'])+'〈旧案の設定を継承〉</span><dl>')
