  m=research['mechanics'][mid];parts.append('<li>'+e(m['title'])+'／代表：'+e(m['exampleNames'])+'<small>参照資料でのSAA状態：'+e(m['auditStatusInReference'])+'。このカード案の実装済み判定ではありません。</small></li>')
