parts.append('<p id="empty" hidden>一致するカードはありません。</p><script>const q=document.getElementById("search"),ch=document.getElementById("character"),ty=document.getElementById("type"),cards=[...document.querySelectorAll(".effect-card")];function filter(){let n=0;for(const c of cards){c.hidden=!c.textContent.toLowerCase().includes(q.value.toLowerCase())||(ch.value&&!c.dataset.character.split(" ").includes(ch.value))||(ty.value&&c.dataset.type!==ty.value);if(!c.hidden)n++;}document.getElementById("count").textContent=n+"件表示";document.getElementById("empty").hidden=n!==0;}q.addEventListener("input",filter);ch.addEventListener("change",filter);ty.addEventListener("change",filter);window.addEventListener("hashchange",()=>{if(location.hash.startsWith("#c-")){q.value="";ch.value="";ty.value="";filter();document.getElementById(location.hash.slice(1))?.scrollIntoView();}});</script></main></html>')
